const modules = [
  {id:'passwords', icon:'🔐', title:'Contraseñas', subtitle:'Protegé el acceso a tus cuentas', learn:{title:'Una contraseña cuida la primera puerta', intro:'Las contraseñas son personales y no se comparten. Una clave extensa y única reduce el riesgo de accesos no autorizados.', points:[['Creá frases largas','Combiná palabras no relacionadas, números y símbolos. Como referencia corporativa, apuntá a 16 caracteres o más.'],['Evitá lo predecible','No uses 123456, fechas de nacimiento, nombres ni secuencias como abcd.'],['Mantenela privada','No la envíes por correo, chat ni se la prestes a colegas. Usá un gestor aprobado si está disponible.'],['Sumá una capa','La verificación en dos pasos protege incluso si alguien consigue tu contraseña.']]}, scenario:{title:'Un acceso “urgente”', person:'Pablo · compañero de oficina', image:'assets/characters/pablo.png', text:'Pablo, tu compañero de oficina, te escribe por chat: “Estoy bloqueado y necesito cerrar una operación. ¿Me pasás tu contraseña por cinco minutos?”', options:['Se la envío: es un compañero y la necesita con urgencia.','Le indico que use el proceso oficial de recuperación o contacte a soporte.','Le presto mi equipo con la sesión abierta.'], answer:1, feedback:'Las credenciales son personales e intransferibles. La urgencia nunca justifica compartirlas; el acceso debe recuperarse por los canales autorizados.'}, quiz:[['¿Cuál es la práctica más segura?', ['Reutilizar una contraseña conocida.','Usar una frase de contraseña larga y única.','Cambiar una letra por un número en mi fecha de nacimiento.'],1,'Una frase larga, única y difícil de predecir protege mejor la cuenta.'],['¿Qué acción compromete una contraseña robusta?', ['Guardarla en un gestor seguro aprobado.','Compartirla por correo no cifrado.','Activar la verificación en dos pasos.'],1,'Una clave fuerte deja de ser segura cuando se comparte por medios inseguros.'],['¿Para qué sirve la verificación en dos pasos?', ['Para sumar una capa de protección además de la contraseña.','Para que la aplicación sea más rápida.','Para evitar actualizar la clave.'],0,'El segundo factor dificulta el acceso aunque una contraseña sea comprometida.']]},
  {id:'data', icon:'🛡️', title:'Protección de datos', subtitle:'Cuidá tu información y la de otras personas', learn:{title:'Los datos requieren decisiones seguras', intro:'La información personal, financiera y de tarjetas puede usarse para fraudes o robos. Cuidarla es importante tanto en la vida diaria como en el trabajo.', points:[['Reconocé información sensible','Documentos, tarjetas, credenciales, fotos privadas y datos de contacto no se comparten sin necesidad.'],['Elegí canales seguros','No envíes información sensible por correos o chats personales si existe un canal seguro para hacerlo.'],['Conectate con cuidado','Evitá operaciones sensibles desde Wi-Fi público. Preferí redes conocidas y protegidas.'],['Actualizá tus herramientas','Las actualizaciones corrigen problemas de seguridad y mantienen protegidos tus dispositivos.']]}, scenario:{title:'La planilla desde el café', person:'Carla · compañera de equipo', image:'assets/characters/carla.png', text:'Carla te escribe: “Estoy en un café con Wi-Fi gratis. ¿Me mandás por acá la planilla con datos de contacto para adelantar trabajo?”', options:['La envío por el chat para no retrasar la tarea.','Le propongo esperar una conexión confiable y usar el canal acordado.','Le saco el título al archivo y se la mando por mensajería.'], answer:1, feedback:'Los datos sensibles no deberían viajar por redes o canales no verificados. Una demora breve es preferible a exponer información.'}, quiz:[['¿Por qué proteger los datos compartidos en internet?', ['Pueden usarse para fraudes o robos.','Hace que las páginas carguen más rápido.','Evita gastar batería.'],0,'Los datos personales pueden ser explotados por personas malintencionadas.'],['¿Qué se recomienda al usar Wi-Fi pública?', ['Ingresar a cuentas sensibles si la red tiene un nombre conocido.','Evitar compras, pagos y operaciones sensibles.','Enviar información sensible solo si es urgente.'],1,'Las redes públicas pueden exponer la información transmitida.'],['¿Qué medida suma protección a una cuenta?', ['Activar la verificación en dos pasos.','Compartir la clave solo con conocidos.','Desactivar actualizaciones.'],0,'La verificación en dos pasos agrega una capa adicional de seguridad.']]},
  {id:'grooming', icon:'👤', title:'Grooming', subtitle:'Detectá y reportá contactos riesgosos', learn:{title:'Las señales importan', intro:'El grooming es una forma de manipulación en línea en la que un adulto busca ganarse la confianza de menores para obtener información, imágenes o encuentros.', points:[['Desconfiá de secretos y presiones','Pedidos de mantener conversaciones ocultas, fotos o datos personales son señales de alerta.'],['Cuidá la información','No compartas ubicación, rutinas, escuela ni imágenes con desconocidos.'],['No enfrentes ni borres evidencia','Conservá capturas y conversaciones relevantes para poder reportar.'],['Acompañá y reportá','Escuchá sin culpar. Bloqueá la cuenta y buscá ayuda en los canales correspondientes.']]}, scenario:{title:'Consulta de una clienta', person:'Sofía · clienta', image:'assets/characters/sofia.png', text:'Sofía comenta que su hijo recibe mensajes de alguien que dice tener su edad, pide fotos y le solicita que no se lo cuente a nadie.', options:['Le recomiendo que el menor continúe hablando para conocer sus intenciones.','Le sugiero guardar evidencia, bloquear el contacto y buscar ayuda de un adulto y canales de denuncia.','Le indico borrar todo para que nadie vea los mensajes.'], answer:1, feedback:'Los secretos, pedidos de imágenes y presión son alertas. Conservar evidencia, bloquear y buscar ayuda protege a la persona afectada.'}, quiz:[['¿Cuál es una señal de alerta?', ['Un contacto pide mantener la conversación en secreto.','Un familiar envía un saludo.','Una aplicación solicita actualizarse.'],0,'Las peticiones de secreto y aislamiento son tácticas frecuentes de manipulación.'],['¿Qué conviene hacer ante un posible caso?', ['Guardar evidencia y pedir ayuda.','Responder con amenazas.','Publicar la conversación en redes.'],0,'Es importante acompañar, conservar evidencia y usar canales seguros de ayuda.'],['¿Qué dato no debe compartirse con desconocidos?', ['La ubicación y rutina.','El color favorito.','Una recomendación de música.'],0,'Ubicación, rutinas e imágenes pueden poner en riesgo la seguridad personal.']]},
  {id:'email', icon:'✉️', title:'Correo personal / corporativo', subtitle:'Usá cada cuenta y canal con cuidado', learn:{title:'Un correo puede abrir una puerta o una trampa', intro:'El correo sirve para conversar, comprar, estudiar y trabajar. Por eso conviene separar las cuentas y mirar cada mensaje con atención antes de actuar.', points:[['Separá lo personal de lo laboral','No reenvíes documentos de trabajo o datos de otras personas a tu correo personal.'],['Verificá antes de actuar','Revisá remitente, dominio, enlaces y adjuntos antes de abrirlos.'],['Informá lo sospechoso','Los mensajes falsos suelen generar urgencia o pedir claves. Pedí ayuda o reportalos.'],['Usá recursos autorizados','Para información de trabajo, compartí archivos solo mediante plataformas y destinatarios aprobados.']]}, scenario:{title:'“¿Me lo reenviás a mi cuenta personal?”', person:'Martín · compañero de equipo', image:'assets/characters/martin.png', text:'Martín te escribe: “No puedo entrar al correo del trabajo. Reenviame el archivo del proyecto a mi cuenta personal, así avanzo desde casa.”', options:['Se lo reenvío porque conozco a Martín.','Le propongo esperar el acceso o usar el proceso y canal acordados.','Le mando capturas por una red social para que no ocupe tanto espacio.'], answer:1, feedback:'Aunque conozcas a la persona, los archivos de trabajo deben circular por los canales definidos. Eso protege la información y permite saber quién accedió.'}, quiz:[['¿Cuándo usar el correo personal?', ['Para reenviar un archivo laboral urgente.','Para guardar una copia de respaldo de un informe.','Para asuntos personales, no para información o gestiones de la empresa.'],2,'El correo personal no tiene los mismos controles que una cuenta de trabajo.'],['¿Qué puede indicar phishing?', ['Un mensaje que genera urgencia y pide credenciales.','Un boletín interno que estabas esperando.','Un correo que ya verificaste con su remitente por otro canal.'],0,'La urgencia y el pedido de datos son señales que requieren verificación.'],['¿Qué hacer con un enlace sospechoso?', ['Abrirlo en una ventana privada.','No interactuar y pedir ayuda o reportarlo.','Reenviarlo a todo el equipo.'],1,'No interactúes con enlaces sospechosos; reportarlos permite una respuesta segura.']]},
  {id:'threats', icon:'⚠️', title:'Amenazas cibernéticas', subtitle:'Reconocé ataques antes de que causen daño', learn:{title:'Reconocer una amenaza permite frenarla', intro:'No todos los ataques se ven igual. Conocer sus señales ayuda a actuar antes de que un mensaje, archivo o enlace afecte a la organización.', points:[['Malware','Es un software diseñado para dañar, alterar o acceder a un equipo sin autorización.'],['Ransomware','Es un tipo de malware que cifra o bloquea archivos y puede exigir un pago.'],['Phishing, smishing y vishing','Buscan engañar por correo, mensaje o llamada para obtener datos o lograr una acción apresurada.'],['Detené y reportá','No abras adjuntos ni enlaces dudosos. Verificá por un canal oficial y avisá al área responsable.']]}, scenario:{title:'El correo que bloquea la cuenta', visual:'✉️', text:'Joaquín recibe un correo que dice: “Tu cuenta será bloqueada hoy. Verificá tus datos ahora” e incluye un enlace.', options:['Abro el enlace rápido para evitar el bloqueo.','Reconozco un posible phishing, no interactúo y lo reporto.','Reenvío el correo a mis compañeros para que también revisen su cuenta.'], answer:1, feedback:'Un correo urgente que pide datos mediante un enlace es una señal típica de phishing. No interactúes y reportalo.'}, quiz:[['¿Qué describe mejor al ransomware?', ['Un programa que cifra o bloquea información.','Una actualización del sistema.','Un método para mejorar el Wi-Fi.'],0,'El ransomware busca impedir el acceso a los datos y puede exigir un rescate.'],['¿Qué tipo de engaño llega por llamada telefónica?', ['Vishing.','Smishing.','Spyware.'],0,'El vishing usa llamadas para presionar o suplantar identidades.'],['¿Qué hacer ante un adjunto inesperado?', ['Abrirlo en modo privado.','Verificar y reportar antes de abrirlo.','Reenviarlo a todo el equipo.'],1,'Detenerse, verificar y reportar limita el impacto de una posible amenaza.']]},
  {id:'social', icon:'🧑‍💻', title:'Ingeniería social', subtitle:'Protegé tu puesto y verificá identidades', learn:{title:'El atacante puede buscar manipular a una persona', intro:'La ingeniería social usa urgencia, confianza o autoridad aparente para lograr que alguien entregue datos, abra un acceso o realice una acción insegura.', points:[['Verificá la identidad','Que alguien conozca tu nombre o rol no prueba que sea quien dice ser. Usá un canal oficial.'],['No compartas secretos','Contraseñas, códigos MFA y datos internos nunca se solicitan por llamada o chat informal.'],['Cuidá el puesto de trabajo','Bloqueá la pantalla al alejarte y resguardá documentos confidenciales.'],['Desconfiá de objetos desconocidos','Un USB encontrado o un visitante que intenta ingresar sin autorización debe reportarse.']]}, scenario:{title:'“Soy de Sistemas, necesito tu código”', visual:'☎️', text:'Una persona llama a Sofía, dice ser de Sistemas y le pide usuario, contraseña y un código MFA para una actualización urgente.', options:['Le doy el código porque conoce mi nombre y sector.','No comparto datos y verifico el pedido con Sistemas por un canal oficial.','Le doy solo el código MFA para que la actualización sea rápida.'], answer:1, feedback:'La urgencia y la supuesta autoridad son recursos de manipulación. Verificá por un canal oficial y no compartas credenciales.'}, quiz:[['¿Qué es tailgating?', ['Ingresar a un sector siguiendo a una persona autorizada.','Actualizar un antivirus.','Cambiar una contraseña.'],0,'No permitas que una persona ingrese a un área restringida sin validar su acceso.'],['¿Qué corresponde al alejarse del puesto?', ['Bloquear la pantalla.','Dejar la sesión abierta por si volvés pronto.','Compartir el equipo con cualquiera.'],0,'Bloquear la pantalla protege información y accesos cuando no estás presente.'],['¿Qué hacer con un USB desconocido?', ['Conectarlo para ver qué contiene.','Reportarlo y no conectarlo.','Llevarlo a casa.'],1,'Un USB puede contener software malicioso; reportarlo evita exponer equipos y datos.']]}
];
