const learnChallenges={passwords:{prompt:'María usaba Maria123. ¿Cuál es una contraseña más segura?',options:['Maria2026!','M4ria123!','Río!Luna_84#Tren'],answer:2,feedback:'Una frase larga, única y sin datos personales es mucho más difícil de adivinar.'},data:{prompt:'¿Cuál de estos elementos requiere mayor protección?',options:['Una noticia pública','El número de una tarjeta','El pronóstico del clima'],answer:1,feedback:'Los datos financieros y personales son sensibles y solo deben tratarse por canales autorizados.'},grooming:{prompt:'¿Qué señal requiere atención inmediata?',options:['Un pedido de mantener secretos y enviar fotos','Una actualización de una aplicación','Un saludo de un familiar'],answer:0,feedback:'Los secretos, la presión y los pedidos de imágenes son señales de alerta.'},email:{prompt:'¿Qué revisás antes de abrir un enlace?',options:['El remitente, dominio y destino del enlace','Solo el asunto','El color del correo'],answer:0,feedback:'Revisar el origen y el destino real ayuda a detectar mensajes fraudulentos.'},threats:{prompt:'Un correo urgente con enlace para “evitar un bloqueo” puede ser…',options:['Phishing','Backup','Firewall'],answer:0,feedback:'El phishing utiliza correos engañosos para generar urgencia y robar información.'},social:{prompt:'¿Qué hacés ante una llamada “urgente” que pide tu código MFA?',options:['Lo comparto para no demorar','Corto y verifico con el área por un canal oficial','Doy solo el código'],answer:1,feedback:'La verificación por un canal oficial evita caer en una suplantación.'}};
const finalQuestions=[{module:'passwords',q:'Un compañero pide tu contraseña por una urgencia. ¿Qué hacés?',o:['La comparto por cinco minutos','Indico el proceso oficial de recuperación','Le presto mi sesión abierta'],a:1},{module:'data',q:'¿Dónde compartís una planilla con datos sensibles?',o:['En una nube personal','Por mensajería','Solo en una plataforma de trabajo autorizada'],a:2},{module:'grooming',q:'Ante pedidos de secretos, fotos y aislamiento, ¿qué corresponde?',o:['Guardar evidencia y pedir ayuda','Continuar para conocer la intención','Borrar todo de inmediato'],a:0},{module:'email',q:'Un correo urgente pide tus credenciales. ¿Qué hacés?',o:['Pido ayuda o lo reporto sin interactuar','Respondo para verificar','Abro el enlace en incógnito'],a:0},{module:'threats',q:'Un mensaje por WhatsApp con un enlace falso para robar datos es…',o:['Vishing','Smishing','Ransomware'],a:1},{module:'social',q:'Al alejarte de tu escritorio, la acción segura es…',o:['Bloquear la pantalla','Dejar todo abierto','Compartir la sesión'],a:0},{module:'passwords',q:'Recibís una aprobación de segundo factor que no solicitaste. ¿Cuál es la mejor respuesta?',o:['Aprobarla si aparece varias veces para que deje de insistir','Rechazarla y verificar el intento por un canal conocido','Compartir el código con soporte para que revise el caso'],a:1},{module:'data',q:'Alguien te pide datos de una persona por un canal distinto al habitual. ¿Qué decisión protege mejor la información?',o:['Enviar solo una parte de los datos para responder rápido','Validar identidad, necesidad y canal adecuado antes de compartir','Reenviar el pedido a una cuenta personal para revisarlo después'],a:1},{module:'email',q:'Una persona conocida envía un archivo inesperado desde una dirección levemente distinta. ¿Qué hacés?',o:['Lo abrís porque el nombre coincide','Verificás el pedido por otro canal antes de abrirlo','Lo reenviás a alguien para que lo pruebe'],a:1},{module:'threats',q:'Un equipo muestra archivos con extensiones desconocidas y un aviso de pago. ¿Qué acción inicial es más adecuada?',o:['Seguir trabajando y reiniciar al finalizar el día','Dejar de usarlo y avisar según el procedimiento disponible','Pagar de inmediato para recuperar los archivos'],a:1}];
